BEGIN;
CREATE TABLE IF NOT EXISTS users(id BIGSERIAL PRIMARY KEY,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'admin',created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS warehouses(id BIGSERIAL PRIMARY KEY,name TEXT UNIQUE NOT NULL,location TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS suppliers(id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL,phone TEXT NOT NULL DEFAULT '',email TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS products(id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL,sku TEXT UNIQUE NOT NULL,category TEXT NOT NULL DEFAULT 'عام',price NUMERIC(12,2) NOT NULL CHECK(price>=0),cost NUMERIC(12,2) NOT NULL CHECK(cost>=0),stock INTEGER NOT NULL DEFAULT 0 CHECK(stock>=0),min_stock INTEGER NOT NULL DEFAULT 5 CHECK(min_stock>=0),warehouse_id BIGINT REFERENCES warehouses(id) ON DELETE RESTRICT,active BOOLEAN NOT NULL DEFAULT true,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS invoices(id BIGSERIAL PRIMARY KEY,number TEXT UNIQUE NOT NULL,date DATE NOT NULL DEFAULT CURRENT_DATE,customer TEXT NOT NULL,total NUMERIC(12,2) NOT NULL DEFAULT 0,cost NUMERIC(12,2) NOT NULL DEFAULT 0,created_by BIGINT REFERENCES users(id));
CREATE TABLE IF NOT EXISTS invoice_items(id BIGSERIAL PRIMARY KEY,invoice_id BIGINT NOT NULL REFERENCES invoices(id) ON DELETE CASCADE,product_id BIGINT REFERENCES products(id) ON DELETE SET NULL,product_name TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0),unit_price NUMERIC(12,2) NOT NULL CHECK(unit_price>=0),unit_cost NUMERIC(12,2) NOT NULL CHECK(unit_cost>=0));
CREATE TABLE IF NOT EXISTS purchases(id BIGSERIAL PRIMARY KEY,date DATE NOT NULL DEFAULT CURRENT_DATE,supplier_id BIGINT REFERENCES suppliers(id) ON DELETE SET NULL,supplier_name TEXT NOT NULL,total NUMERIC(12,2) NOT NULL DEFAULT 0,created_by BIGINT REFERENCES users(id));
CREATE TABLE IF NOT EXISTS purchase_items(id BIGSERIAL PRIMARY KEY,purchase_id BIGINT NOT NULL REFERENCES purchases(id) ON DELETE CASCADE,product_id BIGINT REFERENCES products(id) ON DELETE SET NULL,product_name TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0),unit_cost NUMERIC(12,2) NOT NULL CHECK(unit_cost>=0));
CREATE TABLE IF NOT EXISTS stock_movements(id BIGSERIAL PRIMARY KEY,product_id BIGINT REFERENCES products(id) ON DELETE SET NULL,product_name TEXT NOT NULL,delta INTEGER NOT NULL,reason TEXT NOT NULL,reference_id BIGINT,created_at TIMESTAMPTZ DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_invoices_date ON invoices(date);
CREATE INDEX IF NOT EXISTS idx_purchases_date ON purchases(date);
CREATE INDEX IF NOT EXISTS idx_movements_product ON stock_movements(product_id);
COMMIT;
